    title = f"{d['name']} — {d['h1']['ru']}, {d['city']['ru']}"
    page = (tpl.replace("__TITLE__", html.escape(title))
               .replace("__DESC__", html.escape(d["lede"]["ru"]))
               .replace("__DATA__", json.dumps(d, ensure_ascii=False).replace("</", "<\\/")))
    open(os.path.join(OUT, slug + ".html"), "w").write(page)
    print(slug, len(page))
